insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('wellcorrelation', 'intermediate', 'module', 'm01-from-reading-to-flattening', 1, 'The structural view and the flattened view of the Ekene section ask different questions. Which pair states them correctly?', '["The structural view answers what the section looked like when it was deposited, and the flattened view answers where each surface sits in the ground now.","Both views answer the same question, and the flattened one answers it at a larger vertical scale.","The structural view answers where each surface sits now, and the flattened view answers what the section looked like when it was deposited.","The structural view is a display convention and the flattened view is the measured record held in the tops table."]'::jsonb, 2, 'Reading a section is a statement about position now; flattening is a statement about accumulation then. The first distractor is the classic reversal of the two, and the last embodies the error of treating a flattened display as data.'),
  ('wellcorrelation', 'intermediate', 'module', 'm01-from-reading-to-flattening', 2, 'Ekene-4 carries no TOP_B. What does the Professional tier do about that gap?', '["It counts the gap, excludes Ekene-4 from any interval measured to TOP_B, and leaves the pick unmade.","It estimates the missing TOP_B from the three wells that do carry it and reports the estimate beside the measured picks.","It records TOP_B in Ekene-4 as a thickness of zero metres so that every well contributes to the reading.","It drops Ekene-4 from the section, since a well with three tops cannot be flattened."]'::jsonb, 0, 'This tier counts three wells carrying all four tops and leaves the gap open. The first distractor is the Expert tier''s work borrowed too early, and the second is the classic error of reading absence as zero.'),
  ('wellcorrelation', 'intermediate', 'module', 'm01-from-reading-to-flattening', 3, 'Across Ekene-1 to Ekene-4, what does the TOP_A to TOP_SAND interval measure?', '["35, 49, 45 and 34 m","1498, 1503, 1496 and 1510 m","-50, -62, -45 and -80 m","48, 53, 46 and 60 m, thickest in Ekene-4 and thinnest in Ekene-3"]'::jsonb, 3, 'The interval is a thickness inside each well and is unaffected by the datum. The first distractor is the set of structural relief figures, which is the classic confusion of a relief, measured across wells, with an interval, measured inside one.'),
  ('wellcorrelation', 'intermediate', 'module', 'm01-from-reading-to-flattening', 4, 'What is the structural relief on TOP_A across the Ekene section, and over how many wells?', '["35 m over three wells, because Ekene-4 stops short of the deepest surface","35 m over four wells","34 m over three wells, which is the figure that has to carry its well count","49 m over four wells, which is the relief on the reservoir top"]'::jsonb, 1, 'TOP_A is picked in all four wells, so its relief of 35 m is a four-well figure. The 34 m is TOP_B''s three-well relief and the 49 m is TOP_SAND''s, and mixing them up is the standard slip.'),
  ('wellcorrelation', 'intermediate', 'module', 'm01-from-reading-to-flattening', 5, 'Why is the 34 m relief on TOP_B likely to understate that surface''s true relief across the field?', '["Because relief is deepest minus shallowest, so a smaller number always means a flatter surface.","Because it is measured over three wells, and the absent well is the deepest well on every surface it does reach.","Because TOP_B is the deepest surface in the section and deep picks carry more depth error.","Because Ekene-4''s TOP_B was picked with low confidence and left out of the calculation."]'::jsonb, 1, 'Ekene-4 would very likely have supplied the deepest TOP_B had it reached the surface, so the three-well figure is biased low. The last distractor invents a pick that was never made.'),
  ('wellcorrelation', 'intermediate', 'module', 'm01-from-reading-to-flattening', 6, 'Ekene-4 has no TOP_B pick. What kind of fact is that?', '["A geological fact: the section carrying TOP_B was eroded away beneath that location.","A geological fact: a fault cut the wellbore and removed TOP_B from the column.","An interpretation backlog: the logs reach TOP_B and nobody has committed to a pick.","A drilling fact: the well reached total depth above the surface."]'::jsonb, 3, 'The bit stopped above the surface, so the absence says nothing about whether TOP_B exists there. The three distractors are the other standard reasons a top goes missing, and reading a drilling fact as a geological one is the classic error.'),
  ('wellcorrelation', 'intermediate', 'module', 'm01-from-reading-to-flattening', 7, 'Which reading on the flattening panel is an input rather than a result?', '["The datum, meaning the top you chose to flatten on together with the depth you chose to force it onto.","The shifts, because you decide how far each well should move to bring its flattening pick onto the datum line.","The displayed depths, because they follow the vertical scale and the depth range you choose for the panel.","The intervals, because they are measured off the panel by eye."]'::jsonb, 0, 'The datum is the only interpretation on the panel, and every other reading is downstream of it. Treating the shifts as adjustable is the classic error, since a shift is computed rather than chosen.'),
  ('wellcorrelation', 'intermediate', 'module', 'm01-from-reading-to-flattening', 8, 'The count of Ekene wells carrying all four tops is graded with a tolerance of zero. What does that tolerance say about the reading?', '["That the count was measured more precisely than the depths, which carry a tolerance of 0.01 m.","That counts are graded strictly because they are easier than the continuous readings.","That it is a definition rather than a calculation.","That the engine rounds the count to a whole number before grading it."]'::jsonb, 2, 'A count of wells is a definition, so an answer one off is a wrong model instead of a rounding miss. The first distractor treats a tolerance as a statement about instrument precision, which is the usual misreading.'),
  ('wellcorrelation', 'intermediate', 'module', 'm01-from-reading-to-flattening', 9, 'On the Ekene section, how does the structural signal compare with the growth signal you are trying to read?', '["TOP_A carries 35 m of relief while the growth range is 60 m, the thickest TOP_A to TOP_SAND interval in the section, so the growth signal is the one that dominates the raw panel.","Both are close to 14 m, so a careful reader can separate them by eye on the structural panel.","The structural signal is the 150 m displayed span and the growth signal is 14 m.","TOP_SAND carries 49 m of relief while the whole TOP_A to TOP_SAND variation is 14 m, so the wanted signal is about a quarter the size of the one that dominates."]'::jsonb, 3, 'Fourteen metres against forty-nine is why looking harder at the structural panel does not work. The first distractor quotes Ekene-4''s 60 m interval as though it were the growth range, which is the classic swap of a single interval for a spread of intervals.'),
  ('wellcorrelation', 'intermediate', 'module', 'm01-from-reading-to-flattening', 10, 'What does flattening do to a well''s column?', '["It stretches or squeezes the column so that each interval matches the section average.","It slides the whole column vertically as one rigid block until the chosen surface reaches the chosen depth.","It re-sorts the surfaces into a standard stratigraphic order before drawing them.","It rewrites the well''s picks in the tops table so the chosen surface sits at the datum."]'::jsonb, 1, 'The slide is rigid, so nothing is stretched and nothing can change order. The last distractor is the classic error of believing flattening touches the data rather than the display.'),
  ('wellcorrelation', 'intermediate', 'module', 'm01-from-reading-to-flattening', 11, 'On a section flattened on TOP_A, TOP_A draws as one flat line across all four wells. What can be concluded from that flatness?', '["That TOP_A carries little structural relief across the four wells.","That the TOP_A picks are consistent and correctly correlated from well to well.","Nothing about the geology, because the flatness was imposed by the operation.","That TOP_A was deposited on a level surface, which is what makes it a valid flattening top."]'::jsonb, 2, 'The flat line is a construction guarantee and holds whatever the picks are. Reading it as evidence that the surface is flat is the most common misreading of a flattened panel.'),
  ('wellcorrelation', 'intermediate', 'module', 'm01-from-reading-to-flattening', 12, 'What would a flattened panel look like if the Ekene section were a layer cake?', '["Every surface would draw as a flat line, because every interval would be identical in every well.","The flattening surface would draw flat and the deeper surfaces would fan apart with the structure.","It would look as it does now, since flattening always produces flat lines.","Every well would take the same shift, since a layer cake carries no relief on any surface."]'::jsonb, 0, 'Constant intervals everywhere give a flat-lying stack after flattening. The last distractor confuses constant thickness with an absence of structure, and a layer cake can still be tilted and still gives four different shifts.'),
  ('wellcorrelation', 'intermediate', 'module', 'm01-from-reading-to-flattening', 13, 'Flattening on a surface makes a geological claim. What is it, and where is the claim weakest?', '["That the surface has no structural relief, and it is weakest where the relief is large, as on TOP_SAND at 49 m.","That the surface was near enough level at one moment, and it is weakest on an erosional surface, where different amounts of section have been removed at different wells.","That the surface is present in every well, and it is weakest where a well is missing it.","That the surface is the youngest in the section, and it is weakest where a younger surface exists above it."]'::jsonb, 1, 'Restoring a surface to level restores the geometry of a moment only if the surface was level at that moment. The first distractor confuses the claim being made with the relief being removed.'),
  ('wellcorrelation', 'intermediate', 'module', 'm01-from-reading-to-flattening', 14, 'Which setting does everything graded at this tier use?', '["Flatten on TOP_SAND at a 1450 m datum, which levels the reservoir top.","Flatten on BASE_SAND at a 1450 m datum, which levels the base of the reservoir.","The structural view, with every well drawn at measured depth and no shift applied.","Flatten on TOP_A at a 1450 m datum."]'::jsonb, 3, 'All six graded readings come from flattening on TOP_A at 1450 m. Any other flattening top gives different shifts and a different panel geometry.'),
  ('wellcorrelation', 'intermediate', 'module', 'm01-from-reading-to-flattening', 15, 'The graded reading of 1503 m against Ekene-2''s TOP_SAND is reported correctly in which form?', '["TOP_SAND in Ekene-2 is at a displayed 1503 m, which is close enough to its measured depth for a completion design.","TOP_SAND in Ekene-2 is at 1503 m measured depth and 1565 m displayed depth.","TOP_SAND in Ekene-2 is at a measured 1565 m and displays at 1503 m on the section flattened on TOP_A at 1450 m.","TOP_SAND in Ekene-2 is at 1503 m."]'::jsonb, 2, 'A displayed depth is meaningless without the flattening top and the datum that produced it. The last distractor is the bare number, and the first is the error of handing a displayed depth to work that touches the physical well.'),
  ('wellcorrelation', 'intermediate', 'module', 'm02-choosing-a-datum', 1, 'The phrase ''flatten on TOP_A at 1450 m'' contains two choices. Which statement about them is correct?', '["The datum depth sets the geometry of the panel, and the flattening top only supplies a label for the line that the wells are hung from.","The flattening top sets the geometry of the panel, and the datum depth slides the whole picture along the axis without deforming it.","Both choices change the geometry, so a growth reading is valid only at the datum depth it was taken at.","Neither choice affects the geometry, since flattening changes the display and never the data."]'::jsonb, 1, 'Moving the datum depth adds the same amount to every shift, so the picture slides and nothing deforms. The first distractor reverses the two choices, which is the usual error.'),
  ('wellcorrelation', 'intermediate', 'module', 'm02-choosing-a-datum', 2, 'Two different things in this workflow are called a datum. Which pair distinguishes them correctly?', '["The depth reference datum is chosen afresh for each view, and the flattening datum is the one fixed when the well was logged and cannot be changed.","The depth reference datum applies to measured depths, and the flattening datum applies to true vertical depths once a directional survey exists.","They are two names for one thing, and either can be quoted beside a depth.","The depth reference datum is a property of the well, such as the kelly bushing, and the flattening datum is a display construct you choose."]'::jsonb, 3, 'One is fixed when the well is logged and one is chosen when the panel is drawn. The first distractor reverses them, and the last is the error that lets a displayed depth be quoted as a well depth.'),
  ('wellcorrelation', 'intermediate', 'module', 'm02-choosing-a-datum', 3, 'After flattening the Ekene section on TOP_A, what can the panel no longer tell you?', '["Anything about the structural relief on TOP_A, which is 35 m and readable only in the structural view.","Anything about the TOP_A to TOP_SAND interval, since flattening alters every interval that lies below the datum line.","Anything about how many wells carry all four tops, since the count follows the datum.","Anything about the measured depths of the picks, since flattening rewrites them."]'::jsonb, 0, 'Levelling a surface spends it, and the relief you removed cannot be recovered from the panel that removed it. The first distractor is the classic belief that flattening changes intervals, which it cannot, since both ends of an interval take the same shift.'),
  ('wellcorrelation', 'intermediate', 'module', 'm02-choosing-a-datum', 4, 'What is the flattening shift for a well?', '["That well''s pick of the flattening top minus the datum depth, which gives the distance below the datum.","The datum depth minus the average of the flattening picks across the section.","The datum depth minus that well''s pick of the flattening top.","That well''s pick of the flattening top minus the shallowest such pick in the section."]'::jsonb, 2, 'The datum comes first in the subtraction. The first distractor is the reversal, and it flips every sign in the section so the deepest well appears to move down the display when it moves up.'),
  ('wellcorrelation', 'intermediate', 'module', 'm02-choosing-a-datum', 5, 'Flattening the Ekene section on TOP_A at a 1450 m datum, what is Ekene-4''s shift?', '["-80 m, since 1450 minus 1530 is -80.","80 m, since the well''s TOP_A at 1530 m lies 80 m below the 1450 m datum line.","-45 m, taking 1450 minus 1495.","-62 m, from 1450 minus 1512."]'::jsonb, 0, 'Ekene-4''s TOP_A is picked at 1530 m, and the shift is the datum minus that pick. The first distractor drops the sign, which is the classic error, since the sign is the statement that the well moved up the display.'),
  ('wellcorrelation', 'intermediate', 'module', 'm02-choosing-a-datum', 6, 'Ekene-2''s shift is -62 m and its TOP_SAND is picked at a measured 1565 m. Where does that pick draw on the flattened panel?', '["At a measured depth of 1503 m, because the panel reports the well''s own depths once the datum is applied.","At a displayed depth of 1450 m, since every pick lands on the datum by construction.","At a displayed depth of 1503 m.","At 1510 m displayed."]'::jsonb, 2, 'Displayed depth is the measured depth plus that well''s shift, so 1565 plus -62 gives 1503 m displayed. The first distractor treats a displayed depth as a measured one, and the second stretches the construction guarantee, which applies to the flattening top alone.'),
  ('wellcorrelation', 'intermediate', 'module', 'm02-choosing-a-datum', 7, 'Why does every well''s flattening top land exactly on the datum, whatever its measured depth?', '["Because the engine adjusts each shift until the picks agree, within the grading tolerance of 0.01 m.","Because the four TOP_A picks are close enough together for the line to draw flat.","Because the picks were correlated before flattening, so they already sat at a common depth.","Because displayed depth is the measured depth plus the shift, and the shift is the datum minus that same measured depth, so the measured depth cancels."]'::jsonb, 3, 'It is algebra rather than approximation, which is why it holds for every well and every dataset. The first distractor imagines an iterative fit, and the engine here is one subtraction per well.'),
  ('wellcorrelation', 'intermediate', 'module', 'm02-choosing-a-datum', 8, 'The first check on a flattened panel is that the flattening surface draws as one flat line at the datum. What does passing that check establish?', '["That the flattening picks are correct, since a pick placed in the wrong position would fail to land on the datum line with the rest of them.","That the shifts were applied and every well carries the flattening top, and nothing about whether the picks feeding them are right.","That the section carries no structural relief on the flattening top, which is why that surface draws as a flat line across the wells.","That the intervals below the datum survived the operation."]'::jsonb, 1, 'A wrong pick produces a wrong shift that still lands its own surface exactly on the datum. The first distractor is the classic error of believing a flattened panel can quality-control the surface it was flattened on.'),
  ('wellcorrelation', 'intermediate', 'module', 'm02-choosing-a-datum', 9, 'The four Ekene shifts run from -45 to -80 m, a spread of 35 m, which is also the structural relief on TOP_A. Why must those two agree?', '["Because the engine measures the relief first and derives the shifts from it.","Because the spread of the shifts always matches the relief on the deepest surface in the section.","Because it is a coincidence of these four picks.","Because the datum is a constant, and subtracting a constant from a set of picks preserves the spread of that set."]'::jsonb, 3, 'The shift is the datum minus a pick, so the shifts are the picks displaced by a constant and keep their spread. The second distractor attaches the rule to the wrong surface, since it holds for the flattening top.'),
  ('wellcorrelation', 'intermediate', 'module', 'm02-choosing-a-datum', 10, 'Why is every Ekene shift negative under this tier''s setting?', '["Because the 1450 m datum is shallower than every well''s TOP_A pick, so every well moves up the display.","Because a flattening datum has to be placed above every pick in the section, so the shifts come out negative by definition.","Because measured depth increases downward, so a flattening shift is negative in every section.","Because the wells are structurally low, and low wells take negative shifts."]'::jsonb, 0, 'The sign follows from where the datum was placed relative to the picks and carries no geology. The first distractor is the classic misconception that a datum must be shallower than every pick, when a deeper datum turns all four shifts positive and changes no interval.'),
  ('wellcorrelation', 'intermediate', 'module', 'm02-choosing-a-datum', 11, 'When is a flattening shift positive?', '["When that well''s pick of the flattening top is deeper than the datum.","When the section is flattened on a surface that lies below the interval being measured.","When the datum is deeper than that well''s flattening pick.","When a well lacks the flattening top and the engine supplies a default."]'::jsonb, 2, 'Positive means the well moved down the display toward larger displayed depths. The first distractor is the reversal, which is the condition for a negative shift.'),
  ('wellcorrelation', 'intermediate', 'module', 'm02-choosing-a-datum', 12, 'You choose a flattening datum that falls inside the range of the flattening picks. What do you see?', '["The engine refuses the datum, since it has to lie outside the range of the picks.","Wells shallower than the datum take positive shifts and move down, wells deeper than it take negative shifts and move up, and all of them land on the datum line.","The wells nearest the datum are left unshifted and the rest are moved onto them.","A partly flattened panel, because only the wells below the datum can be moved onto the line."]'::jsonb, 1, 'Mixed signs are ordinary, and the wells converge on the datum from both sides. The last distractor confuses a mixed sign with the genuine partial-flattening case, which arises when a well lacks the flattening top.'),
  ('wellcorrelation', 'intermediate', 'module', 'm02-choosing-a-datum', 13, 'TOP_B is ruled out as a flattening top for the Ekene section. On which criterion?', '["Presence: it is carried by three of the four wells.","Reliability: its picks are the least certain of the four surfaces.","Geometry: it is the deepest surface, so the section would read upward from the datum line.","Relief: at 34 m it has the least relief of the four, so levelling it would change little."]'::jsonb, 0, 'A flattening top a well is missing flattens part of the section and leaves the rest at measured depth. The other three criteria are real considerations elsewhere, and choosing a top a well lacks is the named error here.'),
  ('wellcorrelation', 'intermediate', 'module', 'm02-choosing-a-datum', 14, 'Flatten the Ekene section on TOP_B. What does the engine do with Ekene-4?', '["It interpolates a TOP_B for the well from the neighbouring wells and flattens the whole column on the interpolated value.","It assigns the well a shift of zero and draws it beside the others without comment.","It removes the well from the section altogether, since a well without a pick for the flattening top cannot be drawn at all.","It gives the well no shift, draws it at measured depth, and flags it as lacking the flattening top."]'::jsonb, 3, 'The flag is the point, since a well hung at measured depth beside three flattened neighbours is not comparable to them. The second distractor is the same drawing with the warning removed, which is the outcome that misleads a reader silently.'),
  ('wellcorrelation', 'intermediate', 'module', 'm02-choosing-a-datum', 15, 'Suppose Ekene-2''s TOP_A pick were 10 m too deep. What would the flattened panel show?', '["Ekene-2''s TOP_A sitting 10 m off the datum line, which is how the error would be caught.","TOP_A still drawing as one flat line at the datum, with every other pick in Ekene-2 displaced by 10 m on the display.","Every well displaced by 10 m, since the shifts are computed relative to one another.","No change at all, since flattening changes the display and never the data."]'::jsonb, 1, 'An error in the flattening pick propagates at full size into every other surface in that well, and the flattened surface stays flat throughout. The first distractor assumes the panel can reveal an error in its own flattening pick.'),
  ('wellcorrelation', 'intermediate', 'module', 'm03-displayed-depth', 1, 'What is a displayed depth on a flattened section?', '["The depth the logging tool recorded for that pick.","A position on a panel whose vertical axis was redefined when you chose the datum, valid only in that view.","A measured depth that has been corrected for the deviation of the well.","The depth stored for that pick in the tops table."]'::jsonb, 1, 'A displayed depth exists only inside one flattened view and moves whenever the datum changes, while the measured depth is a property of the wellbore and never moves.'),
  ('wellcorrelation', 'intermediate', 'module', 'm03-displayed-depth', 2, 'Ekene-2 has TOP_SAND at a measured 1565 m and a shift of -62 on this tier''s datum. Where does that pick display?', '["1627 m displayed, since the magnitude of the shift is added to the measured pick of 1565 m.","1503 m displayed, since a displayed depth is the pick plus that well''s shift.","115 m displayed, since the datum is subtracted from the pick.","1515 m displayed, using a shift of -50."]'::jsonb, 1, 'The addition is 1565 plus -62, which gives the graded 1503 m displayed. Adding the magnitude instead of the signed shift is the classic sign error, and it always leaves the pick deeper than it started, which cannot happen on this datum.'),
  ('wellcorrelation', 'intermediate', 'module', 'm03-displayed-depth', 3, 'How is a well''s flattening shift computed on this tier''s datum?', '["That well''s own TOP_A minus the datum, which keeps the shift positive.","The datum minus the shallowest TOP_A in the section.","The mean of the four TOP_A picks minus the datum.","The datum minus that well''s own TOP_A."]'::jsonb, 3, 'The subtraction is 1450 minus that well''s own TOP_A, so Ekene-2 takes 1450 minus 1512, which is -62. Reversing the order flips every sign and sends every column the wrong way.'),
  ('wellcorrelation', 'intermediate', 'module', 'm03-displayed-depth', 4, 'After flattening on TOP_A at 1450 m, where does TOP_A display in each of the four wells?', '["At its own measured depth in every well, since the pick itself did not move.","At 1450 m displayed in Ekene-1 only, because that well anchors the datum.","At 1450 m displayed in every well.","At the mean of the four TOP_A picks, which is where the datum line is drawn."]'::jsonb, 2, 'Substituting the shift into the displayed formula cancels the measured depth and leaves the datum, so the flattening top lands on one flat line by construction. That is the first thing to check on any flattened panel.'),
  ('wellcorrelation', 'intermediate', 'module', 'm03-displayed-depth', 5, 'The completion engineer asks for the depth to perforate the top of the sand in Ekene-2. Which number do you give?', '["1565 m measured, because a perforation is made in a wellbore.","1503 m displayed, because that is the number the flattened section shows for the sand top in that well.","1503 m, quoted without a datum.","53 m, the distance below the flattened TOP_A line."]'::jsonb, 0, 'Anything that touches the physical well takes measured depth. Handing over a displayed depth is the classic error here, and 1503 m looks exactly as much like a depth as 1565 m does.'),
  ('wellcorrelation', 'intermediate', 'module', 'm03-displayed-depth', 6, 'Ekene-3 has TOP_A at a measured 1495 m. What is its flattening shift on the 1450 m datum?', '["-80 m, the largest shift in the section, since Ekene-3 is the deepest well.","-45 m, since 1450 minus 1495 is negative.","+45 m, from 1495 minus 1450.","-50 m, which is Ekene-1''s shift."]'::jsonb, 1, 'The shift is the datum minus that well''s own TOP_A, so 1450 minus 1495 gives -45 m. Ekene-3 is the shallowest well at TOP_A rather than the deepest, and reading across to another well''s shift is a common slip.'),
  ('wellcorrelation', 'intermediate', 'module', 'm03-displayed-depth', 7, 'Ekene-4 has BASE_SAND at a measured 1615 m and a shift of -80. What is the displayed depth, and what does it mean?', '["1535 m measured, since flattening rewrites the tops table.","1535 m displayed, a position on the panel, with nothing in that wellbore at 1535 m.","1695 m displayed, from 1615 plus 80.","1615 m displayed, since BASE_SAND is not the flattening top."]'::jsonb, 1, 'The arithmetic is 1615 plus -80. Reporting 1535 m as a well depth is the error this module exists to prevent, since the measured pick is still at 1615 m.'),
  ('wellcorrelation', 'intermediate', 'module', 'm03-displayed-depth', 8, 'What is the displayed span of the Ekene section on this tier''s datum, and which two displayed depths set it?', '["140 m, from 1450 m down to 1590 m displayed in Ekene-1.","85 m, down to 1535 m displayed.","150 m, from 1450 m down to 1600 m displayed.","133 m, from 1450 m down to 1583 m displayed in Ekene-3."]'::jsonb, 2, 'The shallow end is pinned at the datum because every TOP_A lands there, and the deep end is Ekene-2''s TOP_B at 1662 plus -62, which is 1600 m displayed. The graded span is 150 m.'),
  ('wellcorrelation', 'intermediate', 'module', 'm03-displayed-depth', 9, 'Which well supplies the deep end of the displayed span, and why?', '["Ekene-4, because it carries the deepest measured pick of every top it has, including BASE_SAND at 1615 m.","Ekene-1, because it has the smallest shift in magnitude at -50.","Ekene-2, because it carries the largest measured distance below its own TOP_A at 150 m.","Ekene-3, because it has the shallowest TOP_A at 1495 m."]'::jsonb, 2, 'Flattening removes each well''s own TOP_A depth, so depth below the flattening top sets the deep end, and those distances are 140, 150, 133 and 85 m. Assuming the deepest measured pick wins is the classic error, and Ekene-4 is the counterexample that kills it.'),
  ('wellcorrelation', 'intermediate', 'module', 'm03-displayed-depth', 10, 'On the flattened panel, where does Ekene-4''s deepest pick draw?', '["At 1535 m displayed, the shallowest of the four deep ends.","At 1615 m displayed, since it is the deepest measured pick in the section.","At 1600 m displayed, the bottom of the panel.","At 1662 m displayed, matching the deepest measured pick in the section."]'::jsonb, 0, 'Ekene-4''s deepest pick is BASE_SAND, and 1450 plus 85 gives 1535 m displayed. The deepest well in measured depth draws shallowest once its own TOP_A depth has been removed.'),
  ('wellcorrelation', 'intermediate', 'module', 'm03-displayed-depth', 11, 'What does the displayed span of a section flattened on TOP_A equal?', '["The relief of the deepest surface on the panel.","The difference between the deepest and shallowest measured picks.","The sum of the four flattening shifts.","The largest measured distance from a well''s own TOP_A down to its deepest pick, anywhere in the section."]'::jsonb, 3, 'Since the shallow end is pinned at the datum, the span is set by depth below the flattening top, which is Ekene-2''s 150 m here. It is a property of the picture rather than a thickness.'),
  ('wellcorrelation', 'intermediate', 'module', 'm03-displayed-depth', 12, 'Which quantity does flattening actually change?', '["The measured depth of every pick in the wells that moved.","The thickness between TOP_A and TOP_SAND in each well.","The structural relief of TOP_SAND.","The displayed depth of every pick in the section."]'::jsonb, 3, 'Flattening is a drawing-time addition of one shift per well, so only displayed depths move. Assuming it changes intervals is the misconception that makes people distrust a flattened section.'),
  ('wellcorrelation', 'intermediate', 'module', 'm03-displayed-depth', 13, 'Ekene-2''s TOP_A displays at 1450 m and its TOP_SAND at 1503 m. What is the TOP_A to TOP_SAND interval in that well?', '["53 m, the same as the measured interval of 1565 minus 1512.","53 m displayed, though the measured interval of 1565 minus 1512 is a different number.","1503 m, read straight off the displayed column of the panel.","62 m, the size of that well''s shift."]'::jsonb, 0, 'Both ends of an interval move by the same shift, so the shift cancels and the displayed interval equals the measured one. Treating the two as different quantities is the misconception here.'),
  ('wellcorrelation', 'intermediate', 'module', 'm03-displayed-depth', 14, 'After flattening on TOP_A at 1450 m, what is the structural relief of TOP_SAND?', '["14 m, the spread of the displayed TOP_SAND column.","35 m, the relief of TOP_A, which the flattening transferred to the sand.","49 m, unchanged.","Zero, because flattening removed the relief from the section."]'::jsonb, 2, 'Relief is defined on measured depths, which flattening never edits, so TOP_SAND still runs from 1541 m in Ekene-3 to 1590 m in Ekene-4. Quoting the 14 m displayed spread as relief is the classic confusion.'),
  ('wellcorrelation', 'intermediate', 'module', 'm03-displayed-depth', 15, 'Why is a number built from Ekene-2''s displayed TOP_SAND and Ekene-1''s measured TOP_A meaningless?', '["Because an interval needs two picks from the same well read on the same axis, and this mixes wells and axes.","Because the two wells carry different shifts, so a correction has to be applied first.","Because displayed depths cannot be subtracted from one another.","Because Ekene-1 carries no TOP_SAND pick."]'::jsonb, 0, 'An interval is a difference of two picks in one wellbore, both measured or both displayed. Reaching across columns on a panel is easy to do with a cursor and produces a number with no meaning.'),
  ('wellcorrelation', 'intermediate', 'module', 'm04-growth', 1, 'Why is an interval unchanged by flattening?', '["Because both of its ends sit in the same well and move by the same shift, so the shift cancels in the subtraction.","Because the engine recomputes each thickness after the columns have moved.","Because the shifts in this section are all negative.","Because intervals are stored separately from the tops table."]'::jsonb, 0, 'The algebra is that b plus s minus a plus s leaves b minus a. The result holds for any well, any flattening top and any datum.'),
  ('wellcorrelation', 'intermediate', 'module', 'm04-growth', 2, 'What is Ekene-4''s TOP_A to TOP_SAND interval?', '["1510 m, the displayed depth of its TOP_SAND.","60 m.","80 m, the magnitude of its flattening shift.","1590 m, the measured depth of its TOP_SAND."]'::jsonb, 1, 'The interval is 1590 minus 1530, which is the graded 60 m and the thickest of the four. Reading the displayed column as though it were the interval is the classic slip.'),
  ('wellcorrelation', 'intermediate', 'module', 'm04-growth', 3, 'Which well carries the thinnest A-to-SAND interval, and what is it?', '["Ekene-3 at 1496 m, which is where its TOP_SAND displays on this datum.","Ekene-1 at 48 m, the shallowest well in the section.","Ekene-4 at 60 m, since it carries the largest shift.","Ekene-3 at 46 m, which is the thinnest interval in the section."]'::jsonb, 3, 'The four intervals are 48, 53, 46 and 60 m, so Ekene-3 is the thinnest at 46 m. Its 1496 m is a displayed depth rather than a thickness.'),
  ('wellcorrelation', 'intermediate', 'module', 'm04-growth', 4, 'What is the A-to-SAND growth range across the Ekene section?', '["49 m, the relief of TOP_SAND across the wells.","35 m, the relief of TOP_A across the wells.","14 m, from 60 m minus 46 m.","1510 m displayed."]'::jsonb, 2, 'The growth range is the maximum interval minus the minimum, 60 minus 46, which is the graded 14 m. Answering 49 m quotes the relief of the sand top, which is the confusion this module exists to prevent.'),
  ('wellcorrelation', 'intermediate', 'module', 'm04-growth', 5, 'You flatten the same section on a different top, or move the datum. What happens to the A-to-SAND growth range?', '["It changes, because every well takes a different shift.","It stays at 14 m, because intervals are unchanged by the choice of flattening top or datum.","It falls to zero, because the sand line becomes flat.","It becomes 49 m, the relief of TOP_SAND."]'::jsonb, 1, 'Growth is a property of the section rather than of the view, since both ends of an interval carry the same shift. Flattening changes which variation you can see and never changes the numbers.'),
  ('wellcorrelation', 'intermediate', 'module', 'm04-growth', 6, 'The displayed TOP_SAND column on this datum reads 1498, 1503, 1496 and 1510 m. What is the spread of that column, and what is it?', '["14 m, which is the structural relief of TOP_SAND once flattening has taken out the dip.","49 m, the relief of TOP_SAND.","14 m, which is the growth range of the A-to-SAND interval.","1510 m, the deepest value in the column."]'::jsonb, 2, 'Displayed TOP_SAND is 1450 plus the interval, so the spread of that column is the spread of the intervals, which is 14 m. Calling it relief is the classic confusion, since relief is measured and is 49 m.'),
  ('wellcorrelation', 'intermediate', 'module', 'm04-growth', 7, 'What does a growth range of 14 m fail to tell you?', '["Where between the wells the section thickens.","That the interval is not constant across the four wells.","That the extremes are 14 m apart.","Which wells carry the thickest and the thinnest intervals, if their names were written down."]'::jsonb, 0, 'The range is a spread with no direction in it, so the shape of the change between wells is not recoverable from it. Four wells are four samples and the curve through them is a choice.'),
  ('wellcorrelation', 'intermediate', 'module', 'm04-growth', 8, 'A fifth well is added to the section. What can happen to the growth range?', '["It holds or increases.","It holds, since the range is fixed by the two extreme wells already found.","It decreases, because more wells average the variation out.","It cannot be recomputed without reflattening the whole section."]'::jsonb, 0, 'A new interval either falls inside the current extremes or extends one of them, so a range can only hold or grow. That is why it is a lower bound on the variation in the field and is quoted with the well count.'),
  ('wellcorrelation', 'intermediate', 'module', 'm04-growth', 9, 'What would a layer-cake section look like after flattening on TOP_A?', '["Every well''s TOP_SAND at the same measured depth, which is what a growth range of zero means.","A displayed span of zero across the whole panel.","Every well''s TOP_SAND at the same displayed depth, with a growth range of zero.","Every surface drawn at the datum depth of 1450 m."]'::jsonb, 2, 'A layer-cake section carries the same interval in every well, so the stack below the datum lies flat. Growth range zero is a statement about thicknesses rather than about measured depths.'),
  ('wellcorrelation', 'intermediate', 'module', 'm04-growth', 10, 'What does the 14 m growth range license you to say about the Ekene section?', '["That the interval thickened at a rate this section can be used to compute.","That a fault sits between Ekene-3 and Ekene-4.","That accommodation was not the same at the four locations while the section between TOP_A and TOP_SAND accumulated.","That the sand between TOP_SAND and BASE_SAND is thicker in Ekene-4 than in Ekene-3."]'::jsonb, 2, 'Growth says the room available to fill varied across the wells, and no more than that. A rate needs ages, which this section does not carry, and the sand itself is 25 m in Ekene-4 against 29 m in Ekene-3.'),
  ('wellcorrelation', 'intermediate', 'module', 'm04-growth', 11, 'How do the A-to-SAND intervals relate to the measured depth of TOP_A across the four wells?', '["The interval increases as TOP_A gets shallower, so Ekene-3 carries the thickest section at 46 m.","There is no relationship, since the four intervals are unordered.","The interval matches the size of the shift in each well.","The interval increases as TOP_A gets deeper, in all four wells."]'::jsonb, 3, 'Ordering by TOP_A gives 1495 with 46 m, 1500 with 48 m, 1512 with 53 m and 1530 with 60 m, so the interval thickens into the structural low. That pattern is the qualitative signature of more accommodation where the surface was sinking faster.'),
  ('wellcorrelation', 'intermediate', 'module', 'm04-growth', 12, 'A colleague asks how much the TOP_A to TOP_SAND interval varies across the section. What is the answer?', '["49 m, the structural relief of TOP_SAND, which measures how much that surface varies across the wells.","14 m, which is the A-to-SAND growth range across the wells.","35 m, the structural relief of TOP_A.","150 m, the displayed span of the section."]'::jsonb, 1, 'The question names two surfaces, so it asks about an interval, and variation in an interval is growth. Answering with a relief is the error the tier exists to prevent, and here it is roughly three times too large.'),
  ('wellcorrelation', 'intermediate', 'module', 'm04-growth', 13, 'How much structural relief does TOP_SAND carry across the four wells?', '["49 m.","14 m, the spread of the displayed TOP_SAND column on the flattened panel.","60 m, the thickest A-to-SAND interval in the section.","45 m, which is the relief of BASE_SAND."]'::jsonb, 0, 'Relief is a measured-depth quantity, running from 1541 m in Ekene-3 to 1590 m in Ekene-4. Quoting the 14 m displayed spread instead understates the structure and is the more dangerous direction of the confusion.'),
  ('wellcorrelation', 'intermediate', 'module', 'm04-growth', 14, 'How many picks per well does each quantity use?', '["Relief uses two, growth uses one.","Relief uses one, growth uses two.","Both use two, since both compare wells.","Relief uses one and growth uses two, but only once the section has been flattened onto a datum."]'::jsonb, 1, 'Relief is the spread of one named surface, so one pick per well. Growth is the variation of an interval, which needs a top and a base in each well, and counting the surfaces named in a question tells you which is wanted.'),
  ('wellcorrelation', 'intermediate', 'module', 'm04-growth', 15, 'Why must the relief of TOP_B be quoted as 34 m over three wells?', '["Because the fourth value was removed as an outlier.","Because TOP_B lies below the flattening top.","Because relief always excludes the deepest well.","Because Ekene-4 reached total depth above TOP_B, so the figure rests on three of the four wells."]'::jsonb, 3, 'Ekene-4 carries no TOP_B pick, so it cannot contribute to the spread. Dropping the well count is how a three-well number gets read as a four-well one.'),
  ('wellcorrelation', 'intermediate', 'module', 'm05-missing-tops', 1, 'Ekene-4 reached total depth above TOP_B. Which set of picks does the well carry, and what occupies its TOP_B slot?', '["TOP_A at 1530 m, TOP_SAND at 1590 m and BASE_SAND at 1615 m, with TOP_B recorded as 0 m so that every well in the project holds a value for all four of the named surfaces.","All four tops, since TOP_B was carried across from the neighbouring wells.","TOP_A at 1530 m, TOP_SAND at 1590 m and BASE_SAND at 1615 m, with the TOP_B slot left blank because the surface was never drilled in that hole.","TOP_A and TOP_SAND only, because the well ended above BASE_SAND."]'::jsonb, 2, 'Ekene-4 carries three picks and a blank fourth slot. Recording the absence as 0 m is the classic error, because a zero is a depth and would claim a pick at the surface.'),
  ('wellcorrelation', 'intermediate', 'module', 'm05-missing-tops', 2, 'What does a blank in a tops table record?', '["That nobody observed that surface in that particular well.","That the surface sits at a depth of zero in that well, which is why a mean depth across the section drops as soon as the well is included in it.","That the tops table is incomplete and needs to be repaired before the section can be analysed.","That the surface is absent here."]'::jsonb, 0, 'A blank records an absence of data and makes no claim about where the surface is. Reading it as a zero is the classic error, since a zero is a depth that every calculation will happily consume.'),
  ('wellcorrelation', 'intermediate', 'module', 'm05-missing-tops', 3, 'Which explanation for Ekene-4''s missing TOP_B is supported by the Ekene section on its own?', '["A fault cut out the interval that contains TOP_B.","TOP_B was eroded before the overlying section arrived.","The interpreter has not picked TOP_B in this well yet.","The well reached total depth above TOP_B, so the surface was never drilled in that hole, and the deepest pick in the well being BASE_SAND at 1615 m is what makes this explanation available from the section alone."]'::jsonb, 3, 'Only the shallow total depth is knowable from the section itself. Faulting, erosion and an unfinished pick each need evidence from outside the section, and claiming one of them from a blank alone is the classic overreach.'),
  ('wellcorrelation', 'intermediate', 'module', 'm05-missing-tops', 4, 'Flattening the Ekene section on TOP_A at a 1450 m datum, what is Ekene-4''s flattening shift?', '["It cannot be computed, because Ekene-4 is missing TOP_B and therefore has an incomplete column that no datum can be applied to.","-80 m","80 m, since the well moves by that distance to reach the datum.","-45 m, matching the smallest shift on the section."]'::jsonb, 1, 'The shift is the datum minus the well''s own TOP_A, 1450 minus 1530. Flattening on TOP_A needs TOP_A alone, so the missing TOP_B does not prevent it, and the sign is negative because the well moves up the display.'),
  ('wellcorrelation', 'intermediate', 'module', 'm05-missing-tops', 5, 'Which well carries the thickest TOP_A to TOP_SAND interval on the Ekene section, and what does that mean for the growth range?', '["Ekene-2 at 53 m, because Ekene-4 is missing a top and has to be dropped from the interval analysis before the growth range can be computed across the remaining wells.","Ekene-3 at 46 m, which sets both ends of the range.","Ekene-1 at 48 m.","Ekene-4 at 60 m, so the well with the missing top supplies the maximum end of the 14 m growth range."]'::jsonb, 3, 'Ekene-4''s interval is 1590 minus 1530, which is 60 m, the largest on the section, and the range is 60 minus 46. Discarding a well because one of its other tops is absent is the classic error, since it throws away the maximum of the quantity being measured.'),
  ('wellcorrelation', 'intermediate', 'module', 'm05-missing-tops', 6, 'Structural relief on TOP_B across the Ekene section is 34 m. How should that figure be reported?', '["As a four-well number, matching the four wells drawn on the section.","As a displayed figure, because relief is read after flattening.","As a three-well number, since Ekene-1, Ekene-2 and Ekene-3 carry TOP_B and Ekene-4 does not, so the figure describes those three wells and says nothing about what TOP_B does under Ekene-4.","As an estimate, because one well is missing the surface."]'::jsonb, 2, 'A statistic inherits the wells that produced it. Quoting a three-well figure without its denominator is the classic error, because a reader will assume it covers every well on the section.'),
  ('wellcorrelation', 'intermediate', 'module', 'm05-missing-tops', 7, 'How many Ekene wells carry all four tops, and what is being counted?', '["Three, and what is counted is wells whose row holds a pick for every one of the four surfaces.","Four, because four wells are drawn on the section, four wells take a flattening shift and four wells contribute a TOP_A to TOP_SAND interval to the growth range.","Fifteen, which is the number of picks present across the section out of the sixteen slots that four wells and four tops make.","One, the number of wells missing a top."]'::jsonb, 0, 'The count is of wells with a complete column, and Ekene-4 fails that test. Counting the four wells on the section is the classic error, since attendance is not the same as a complete column.'),
  ('wellcorrelation', 'intermediate', 'module', 'm05-missing-tops', 8, 'In the Professional capstone, the field for wells carrying all four tops is graded with what tolerance?', '["0.5, because a count is an integer and the grader rounds any answer within half a unit to the nearest whole number before comparing it with the key.","Zero, so it must be exact.","0.01, matching every other field on the capstone list.","1, so that either three or four scores the mark."]'::jsonb, 1, 'The migration gives that field a tolerance of 0, while the five metre-denominated fields carry 0.01. Assuming a count field has a margin is the classic error, since there is no such thing as being close to three wells.'),
  ('wellcorrelation', 'intermediate', 'module', 'm05-missing-tops', 9, 'What happens to the count of wells carrying all four tops when you re-flatten the section on a different top and datum?', '["It stays at three, because flattening moves picks up and down the display and never adds or removes one.","It changes, because a different flattening top puts different wells on the datum and a well only counts as complete once its own flattening pick has landed on the datum line.","It rises to four once the datum sits above every pick.","It cannot be read from a flattened panel."]'::jsonb, 0, 'The count is a property of the tops table and travels with it into any view. Treating it as a property of the drawing is the classic error, since flattening changes displayed depths and nothing else.'),
  ('wellcorrelation', 'intermediate', 'module', 'm05-missing-tops', 10, 'A correlation line reaches a well that has no pick for the top it is drawing. What does the line do?', '["It bridges the gap to the next well that carries the top.","It places an interpolated point estimated from the neighbouring wells.","It stops, because the line is built by looking the top up in each well in section order and a well that returns nothing contributes no point, so there is no placeholder and no interpolated depth.","It is removed from the section entirely."]'::jsonb, 2, 'Stopping is a property of the tops table rather than a rendering choice. Bridging or interpolating is the classic error, because it converts an expectation into something a reader will quote as data.'),
  ('wellcorrelation', 'intermediate', 'module', 'm05-missing-tops', 11, 'You are handed a flattened Ekene section on which the TOP_B line carries a fourth point in Ekene-4. What does that point represent?', '["A geological claim that TOP_B was found in Ekene-4 after the section was first drawn, which should be adopted into the tops table once the figure has been checked.","A drawing error, since there is no TOP_B observation below Ekene-4''s total depth for any point to represent.","A legitimate reading, because the flattened view can place a surface a well did not reach by using the other wells'' shifts.","A rendering default that carries no meaning."]'::jsonb, 1, 'A geological claim needs an observation, and the hole ended above TOP_B. Reading the fourth point as a discovery is the classic error, since a fabricated point renders identically to a real one.'),
  ('wellcorrelation', 'intermediate', 'module', 'm05-missing-tops', 12, 'How does flattening the Ekene section affect the TOP_B correlation line?', '["Both change, since flattening recomputes the line from the datum and can extend it into a well whose pick was previously outside the drawn depth range of the panel.","Neither changes, because the line is drawn from measured depths.","Its membership grows to four wells.","Its shape changes because each point moves by its own well''s shift, and its membership does not change, so it reaches three wells before and after."]'::jsonb, 3, 'Flattening operates on picks that exist and has nothing to operate on where a pick is absent. Expecting membership to change with the datum is the classic error, and a line that did grow or shrink would mean something other than flattening had touched the data.'),
  ('wellcorrelation', 'intermediate', 'module', 'm05-missing-tops', 13, 'Where does a defensible estimate of Ekene-4''s TOP_B belong?', '["In the tops table as Ekene-4''s TOP_B, since an estimate that comes with a stated method and a stated range is at least as reliable as a pick made on a noisy log.","In the tops table, provided the correlation line on the figure still stops at the third well.","Beside the data, labelled as an estimate.","In the tops table once a reviewer has signed it off."]'::jsonb, 2, 'A tops table has room for a well, a top name and a depth, and no room for how the depth came to be there. Entering an estimate there is the classic error, because within a week nobody can tell it from a measurement.'),
  ('wellcorrelation', 'intermediate', 'module', 'm05-missing-tops', 14, 'A colleague types a defensible estimate into Ekene-4''s TOP_B slot in the tops table. What does that entry do to the count of wells carrying all four tops, and why is the change dangerous?', '["It raises the count from three to four, and the danger is that a complete tops table looks healthier to every automated check than an incomplete one, so nothing flags the fabrication.","It leaves the count at three, since an estimate is not a pick.","It raises the count to four, which is the correct figure once the estimate exists.","It has no effect on any count."]'::jsonb, 0, 'The count is computed from the table, so an entered estimate corrupts it directly and silently. Assuming the discipline protects the number is the classic error, because the software reads the slot rather than the intent behind it.'),
  ('wellcorrelation', 'intermediate', 'module', 'm05-missing-tops', 15, 'The tier above this one produces a prediction for Ekene-4''s TOP_B. What happens to Ekene-4''s TOP_B slot in the tops table?', '["It is filled with the prediction, because a prediction that carries a stated uncertainty is a stronger record than a blank and lets downstream tools run on a complete section.","It stays blank, because a prediction is an estimate and estimates live beside the data rather than inside it.","It is filled with the prediction and flagged, so that the count of wells carrying all four tops becomes four with a note attached.","It is removed from the table."]'::jsonb, 1, 'A prediction with a stated uncertainty is more trustworthy than a guess and is still not a measurement. Promoting it into the tops table is the classic error, and it also moves the graded well count off its exact value of three.'),
  ('wellcorrelation', 'intermediate', 'module', 'm06-the-flattening-workflow', 1, 'Why does the flattening workflow require you to read the measured section before choosing a datum?', '["Because the measured view is where interval thicknesses are computed.","Because structural relief exists only in the measured view, and flattening removes exactly that information, so the relief figures have to be written down before the datum is applied or they cannot be recovered from the panel.","Because the datum cannot be chosen until the shifts are known.","Because the tops table is only complete in that view."]'::jsonb, 1, 'Relief is a structural quantity and the flattened panel has had it removed by construction. Skipping the measured view is the classic error, since it removes the only view in which structure can be read at all.'),
  ('wellcorrelation', 'intermediate', 'module', 'm06-the-flattening-workflow', 2, 'On the Ekene section flattened on TOP_A at a 1450 m datum, how is each well''s shift obtained?', '["As the well''s TOP_A minus 1450, giving 50, 62, 45 and 80 m, since a shift is a distance and distances are reported without a sign.","As 1450 minus the shallowest TOP_A on the section, so every well takes the same shift of -45 m.","As the average of the four TOP_A picks minus 1450.","As 1450 minus that well''s own TOP_A pick, giving -50, -62, -45 and -80 m."]'::jsonb, 3, 'The shift is the datum minus the well''s own flattening pick, computed once per well. Dropping the sign is the classic error, because it reverses the direction the column moves on the display.'),
  ('wellcorrelation', 'intermediate', 'module', 'm06-the-flattening-workflow', 3, 'Ekene-2 picks TOP_SAND at 1565 m and takes a shift of -62 m. What is its TOP_SAND displayed depth, and what is that number not?', '["1503 m displayed, and it is not the depth of the surface in the ground, which is still 1565 m.","1627 m displayed, obtained by adding the magnitude of the shift, and it is the depth the surface would be logged at if the well were re-drilled to the datum.","1565 m, because flattening changes the drawing and leaves the reported depth alone.","1450 m, since the flattening puts every pick on the datum."]'::jsonb, 0, 'A displayed depth is the measured pick plus that well''s shift, and 1503 is the graded capstone value. Handing a displayed depth upward as a measured one is the classic error, since it becomes a wrong contour and then a wrong volume.'),
  ('wellcorrelation', 'intermediate', 'module', 'm06-the-flattening-workflow', 4, 'What happens to the TOP_A to TOP_SAND interval when the section is flattened?', '["It compresses towards the datum, so the four intervals converge on their mean and the growth range shrinks from 14 m to zero as the flattening top is levelled.","It changes with the datum, so a datum of 1450 m gives different intervals from a datum of 1500 m.","Nothing, it stays at 48, 53, 46 and 60 m.","It becomes readable only on the flattened panel."]'::jsonb, 2, 'Both ends of an interval take the same shift, so the shift cancels out of the difference. Expecting a thickness to move with the datum is the classic error, and that invariance is what makes flattening safe to do.'),
  ('wellcorrelation', 'intermediate', 'module', 'm06-the-flattening-workflow', 5, 'On a section flattened on TOP_A at 1450 m, one well shows TOP_A at a displayed depth other than 1450 m. What does that tell you?', '["The datum was set below that well''s TOP_A pick.","That well''s shift is wrong, so every displayed depth in it is wrong by the same amount, and the usual cause is a well that lacks the flattening top and is therefore drawn at its measured depth beside wells that have been moved.","That well has the thickest interval on the section.","The panel is clipped at the top of the display."]'::jsonb, 1, 'The flattening pick plus its shift is the datum by definition, so a well off the line has bad arithmetic behind it. Reading numbers off that well before spotting it is the classic error.'),
  ('wellcorrelation', 'intermediate', 'module', 'm06-the-flattening-workflow', 6, 'A single well on a flattened section carries a shift that is wrong by 12 m. Which reading in that well is still correct?', '["Its interval thicknesses, because a wrong shift moves both ends of an interval equally and cancels out of the difference.","Its displayed depths, because the shift is applied once when the panel is drawn and the stored picks the depths are read from were never altered by it, so the numbers on the panel remain true.","Its structural relief against the neighbouring wells, because relief is a measured quantity that flattening was never able to change in the first place.","Every reading in the well, since the shift only affects the drawing."]'::jsonb, 0, 'A bad shift corrupts every displayed depth in the well and leaves every interval in it intact. Trusting the displayed depths because the stored picks are untouched is the classic error, since the display is where the shift is applied.'),
  ('wellcorrelation', 'intermediate', 'module', 'm06-the-flattening-workflow', 7, 'Which quantities from a flattened section are safe to quote without naming the view they came from?', '["Depths, because a depth is a depth and the reader can always recover the measured value by adding the well''s shift back on if they need it.","Only the displayed span, which is defined on the panel.","Nothing from a flattened section is safe to quote.","Thicknesses and counts, because neither depends on the frame the section is drawn in."]'::jsonb, 3, 'Intervals and counts survive any datum, while depths belong to a view. Quoting a depth bare is the classic error, because nothing in the number tells the reader which frame produced it.'),
  ('wellcorrelation', 'intermediate', 'module', 'm06-the-flattening-workflow', 8, 'Why does the quality control pass require the count of wells carrying all four tops to be stated in the report?', '["Because the capstone grades that count exactly.","Because the count changes with the datum chosen.","Because it tells the reader that some figures below rest on fewer wells than others, so a three-well statistic and a four-well statistic sitting side by side can be told apart rather than assumed to share a denominator.","Because a complete section cannot be flattened otherwise."]'::jsonb, 2, 'The count is the denominator the rest of the report is read against. Leaving it out is the classic error, since it lets a reader treat a three-well figure as covering the whole section.'),
  ('wellcorrelation', 'intermediate', 'module', 'm06-the-flattening-workflow', 9, 'The displayed span you are about to report is longer than the span you can measure on the drawn panel. What has the check caught?', '["A growth signal, because a section that thickens between the wells produces a span on the picks that is larger than the span the panel can draw at a single datum.","A missing top, since Ekene-4 has no TOP_B and the span was computed over four wells.","A shift that was applied to some surfaces and not others.","A clipped view that is not showing the whole column."]'::jsonb, 3, 'The span check compares the picks against what the drawing shows, and a shortfall in the drawing means the view is clipped. Reading the gap as a geological signal is the classic error.'),
  ('wellcorrelation', 'intermediate', 'module', 'm06-the-flattening-workflow', 10, 'On the Ekene section flattened on TOP_A at 1450 m, what determines which pick sits deepest on the panel?', '["The deepest measured pick on the section, which is Ekene-4''s BASE_SAND at 1615 m, since flattening slides whole columns and cannot change which pick lies lowest.","The largest measured distance below its own well''s TOP_A, which is 140, 150, 133 and 85 m across the four wells.","The well with the largest shift, which is Ekene-4 at -80 m, because the largest shift carries its column furthest down the display.","The datum, which fixes the deep end at 1450 m."]'::jsonb, 1, 'A displayed depth is 1450 plus the pick''s distance below its own well''s TOP_A, so Ekene-2''s 150 m sets the deep end. Assuming the deepest measured pick stays deepest is the classic error, because depth below the flattening top governs the display rather than raw depth.'),
  ('wellcorrelation', 'intermediate', 'module', 'm06-the-flattening-workflow', 11, 'Ekene-4 holds the deepest measured pick of every top it carries. Where does it draw on the flattened panel?', '["Shallowest of the four wells, with its deepest displayed pick at 1450 plus 85, which is 1535 m.","Deepest of the four wells, because a well whose picks are all deeper than its neighbours'' keeps that ordering once every column has been slid onto a common datum line.","At the same depth as the others, since flattening levels the whole section.","It cannot be drawn, because it lacks TOP_B."]'::jsonb, 0, 'Ekene-4''s deepest pick sits only 85 m below its own TOP_A, the smallest such distance on the section. Carrying the measured ordering into the flattened view is the classic error.'),
  ('wellcorrelation', 'intermediate', 'module', 'm06-the-flattening-workflow', 12, 'The capstone field for Ekene-4''s flattening shift is graded in metres with a tolerance of 0.01. Why does reporting 80 score nothing?', '["Because the field is graded as a count with a tolerance of zero.","Because the graded value is 1530 m, the well''s own TOP_A pick.","Because the panel reports the shift as 1535 m.","Because the answer is -80 m and the sign records that the well moves up the display to reach the datum, and 80 is not within 0.01 of -80, so the tolerance offers no shelter at all."]'::jsonb, 3, 'The sign is part of the answer and a 0.01 m window is nowhere near wide enough to cross it. Reporting the magnitude alone is the classic error, since it describes a well moving down instead of up.'),
  ('wellcorrelation', 'intermediate', 'module', 'm06-the-flattening-workflow', 13, 'The capstone field for the displayed depth span of the section expects 150 in metres. Which two numbers are the tempting wrong answers, and why?', '["1662 and 1512, the deepest and shallowest measured picks in Ekene-2, because the span is defined on the well that supplies it and is read from the tops table rather than from the panel.","60 and 14, the thickest interval and the growth range, because a span quoted in metres is a thickness and thicknesses are the view independent quantities on the panel.","1600 and 1450, the deepest displayed pick and the datum, because both are real readings on the panel while the field asks for the difference between them.","1535 and 1450, both taken from Ekene-4."]'::jsonb, 2, 'The span is a difference between two depths and shares its unit with them, which is what makes the confusion easy. Entering 1600 or 1450 is the classic error, since each is a genuine reading on the panel and neither is the field.'),
  ('wellcorrelation', 'intermediate', 'module', 'm06-the-flattening-workflow', 14, 'Of the six graded fields in the Professional capstone, how many are denominated in metres with a tolerance of 0.01?', '["Six, since every field on the list is a depth or a distance in metres and the grader applies the same 0.01 window to all of them before comparing with the key.","Five, with the sixth being the well count, which is a count graded exactly.","Four, because the growth range and the well count are both counts.","Three, one for each module that feeds the capstone."]'::jsonb, 1, 'The migration gives five fields the unit m at tolerance 0.01 and gives the well count the unit count at tolerance 0. Assuming a uniform window across the list is the classic error.'),
  ('wellcorrelation', 'intermediate', 'module', 'm06-the-flattening-workflow', 15, 'What does this tier hand upward to the Expert tier?', '["The growth measurement and the still open gap in Ekene-4.","A completed tops table, because the Professional workflow closes the gap in Ekene-4 by estimating TOP_B from the three wells that carry it before the section is passed on.","The structural relief figures, which the Expert tier converts directly into the missing surface.","The displayed depths, which become the Expert tier''s only inputs."]'::jsonb, 0, 'This tier measures growth and leaves the blank open, and the Expert tier is where a prediction for the missing pick is produced. Closing the gap here is the classic error, since it would hand up a fabricated column.'),
  ('wellcorrelation', 'intermediate', 'final', null, 1, 'Ekene-4''s shift of -80 m was derived from its TOP_A pick. Which of that well''s picks does the shift apply to?', '["Only the picks below TOP_A, since the section above the flattening top stays where it was.","Only TOP_A, since each surface takes a shift derived from its own pick.","Every pick in the well, scaled by how far it lies below TOP_A.","Every pick in the well, because the column moves as one rigid block."]'::jsonb, 3, 'A shift belongs to the well rather than to the surface it was computed from. The last distractor is the classic error of imagining a stretch, and a rigid slide moves every pick by the same amount.'),
  ('wellcorrelation', 'intermediate', 'final', null, 2, 'Under this tier''s setting Ekene-4 takes the largest shift at -80 m and Ekene-3 the smallest at -45 m. What does that ranking reflect?', '["The thickness of each well''s TOP_A to TOP_SAND interval, 60 m in Ekene-4 against 46 m in Ekene-3.","How far each well''s TOP_A pick lies from the datum, so the deepest well travels furthest up the display.","The structural relief on TOP_SAND, which is 49 m across the section.","The order the wells sit in on the panel, since shifts accumulate left to right."]'::jsonb, 1, 'The magnitude of a shift is the distance from that well''s flattening pick to the datum. The first distractor reads the shift as a growth measurement, which is the classic conflation this tier exists to break.'),
  ('wellcorrelation', 'intermediate', 'final', null, 3, 'You keep TOP_A as the flattening top and move the datum depth deeper. Which reading changes?', '["The TOP_A to TOP_SAND interval in Ekene-4, which is 60 m on the flattened panel.","The displayed span of the section, which is 150 m from the shallowest displayed pick to the deepest.","Every displayed depth, including the 1503 m against Ekene-2''s TOP_SAND.","The growth range of 14 m, the difference between the thickest and the thinnest interval."]'::jsonb, 2, 'Moving the datum depth alone slides the whole picture, so displayed depths move together and every difference between them survives. Expecting the span to move is the usual slip, and both of its ends shift by the same amount.'),
  ('wellcorrelation', 'intermediate', 'final', null, 4, 'The four Ekene wells are drawn evenly spaced in well-number order. What can be quoted from the panel?', '["The ranking of the wells on a surface and the relief of that surface, and no dip angle, because the horizontal axis carries no distance.","A dip angle, since the wells are drawn evenly spaced along the panel and the vertical scale of the section is known and printed on the axis.","Nothing quantitative, until the wells are redrawn at their map distances.","An apparent dip, which becomes a true dip once the section is flattened."]'::jsonb, 0, 'Even spacing is a drawing convention, so the panel gives sequence rather than gradient. Quoting a dip from a correlation panel is the standard error, and gradient comes from a map.'),
  ('wellcorrelation', 'intermediate', 'final', null, 5, 'This tier asks you to label every number you write down by kind. Which set of kinds does it use?', '["Measured depth, displayed depth, relief, growth and prediction.","Displayed depth, datum, tolerance, growth and span.","Measured depth, displayed depth, interval, shift and count.","Measured depth, true vertical depth, subsea depth, interval and relief."]'::jsonb, 2, 'Those five kinds behave differently when the datum changes, and most mistakes at this tier are one kind being treated as another. The first distractor includes prediction, which belongs to the Expert tier.'),
  ('wellcorrelation', 'intermediate', 'final', null, 6, 'What is the intended way to use the flattening panel at this tier?', '["Predict a reading from the pick table and the rules, write the prediction down, then open the panel and compare.","Read the value off the panel first, then work backwards to a hand calculation that reproduces it.","Use the panel for the continuous readings and hand arithmetic for the counts, since counts carry no tolerance.","Accept the panel''s readings without checking them by hand, since the engine behind the panel is exact closed-form arithmetic rather than a fit."]'::jsonb, 0, 'A prediction that matches confirms the rule you used and a prediction that misses tells you which rule is wrong. The last distractor turns exactness into a reason not to check, when exactness is what makes checking possible.'),
  ('wellcorrelation', 'intermediate', 'final', null, 7, 'Which habit does this tier require when reporting a number computed over some of the wells?', '["Quote the number on its own, since the well count belongs in a method section rather than beside the value itself.","Report only four-well figures, since a figure computed over three wells cannot be compared with them on the same footing.","Fill the missing well with the average of the others so the sample size matches.","Carry the sample size with the number everywhere it appears, including where it sits beside four-well figures."]'::jsonb, 3, 'A three-well number stays a three-well number wherever it is written. The last distractor fills a gap with an invention, which is the error this section is built to teach against.'),
  ('wellcorrelation', 'intermediate', 'final', null, 8, 'You can compute all four TOP_A to TOP_SAND intervals from the pick table with a pencil. Why draw the flattened panel as well?', '["Because the intervals read off the panel differ from the measured ones once a datum is applied.","Because the panel shows whether the thickening runs systematically across the section, and it checks itself by drawing the flattening surface flat.","Because hand arithmetic on an interval stops being reliable once a well lacks a top.","Because the panel computes the intervals more precisely than hand arithmetic."]'::jsonb, 1, 'Four numbers in a column do not say whether the trend is systematic or scattered, and those are different geological claims. The first distractor contradicts the invariance of intervals under flattening.'),
  ('wellcorrelation', 'intermediate', 'final', null, 9, 'Of the six graded readings at this tier, which is graded with no tolerance at all?', '["The count of wells carrying all four tops, which is 3.","The Ekene-4 flattening shift of -80 m, because a sign cannot be approximate.","The displayed span of 150 m, because it is read off the axis rather than computed.","The growth range of 14 m, because it is a difference between two intervals."]'::jsonb, 0, 'The other five are continuous quantities in metres graded to 0.01. A count is a definition, so there is nothing for a tolerance to do.'),
  ('wellcorrelation', 'intermediate', 'final', null, 10, 'Why does it help that TOP_A is the shallowest of the four Ekene surfaces?', '["The structural relief on TOP_A is the smallest of the four surfaces at 35 m, so flattening on it removes the least from the display.","The shifts all come out negative, which is the sign convention the section engine expects when it draws a flattened panel.","The displayed span shrinks, so more of the section fits on the panel.","Every other pick then draws below the datum line, so its displayed depth below that line is its distance from TOP_A in that well."]'::jsonb, 3, 'Flattening on the shallowest surface turns every deeper pick into a single downward reading from one line. The second distractor treats a sign convention as a requirement, and the engine expects no particular sign.'),
  ('wellcorrelation', 'intermediate', 'final', null, 11, 'Flattening the Ekene section on TOP_A makes the panel an argument about what?', '["The structural shape of TOP_A, now that it has been drawn as a single clean line.","What accumulated below TOP_A, since a difference between wells at a deeper surface is now a difference in the interval from TOP_A.","The total depth each well reached, which sets how much of the column is displayed.","The relative quality of the four TOP_A picks, which the flat line tests."]'::jsonb, 1, 'Levelling a surface removes its relief and turns every deeper separation into a thickness. The first distractor is the classic reading of a flattened panel as though it still carried structure on the surface it levelled.'),
  ('wellcorrelation', 'intermediate', 'final', null, 12, 'In this tier''s language, what is the structural view?', '["Every well given the same non-zero shift, so the section keeps its shape and moves down the panel.","The view produced by flattening on the shallowest surface in the section.","Every well given a shift of zero, so displayed depth equals measured depth everywhere.","The view produced when the datum depth is set to the shallowest pick."]'::jsonb, 2, 'Structural mode is the special case of the same arithmetic with every shift set to zero. The first distractor describes a rigid move of the whole panel, which is what changing the datum depth does to a flattened view.'),
  ('wellcorrelation', 'intermediate', 'final', null, 13, 'What does choosing a flattening datum not commit you to?', '["Claiming that the flattening surface was near enough level at one moment in time.","Claiming that the flattening pick is reliable in every well, since an error in it moves that whole column.","Choosing what the panel is about, since levelling one surface makes it an argument about the section below.","Believing anything about the data, since the tops table is unchanged and switching back to the structural view is free."]'::jsonb, 3, 'The three distractors are the real commitments that come with the choice, and the data is not one of them. Believing that flattening alters the record is the misconception being tested.'),
  ('wellcorrelation', 'intermediate', 'final', null, 14, 'On the Ekene section the TOP_B correlation line reaches three wells and stops. What is the right reading of that?', '["It is a correct statement about what has been observed, and the gap is left open.","It is unfinished work, and the line should reach the fourth well once a pick has been estimated.","It is a sign that TOP_B does not exist beneath Ekene-4, since the well drilled through that level.","It is a display limitation, and the line will join once the panel is set to the right datum."]'::jsonb, 0, 'A line that stops short is an honest picture of where a surface has been seen. The first distractor is the classic urge to complete a line, which converts an observation into a guess that nothing downstream can tell apart from a pick.'),
  ('wellcorrelation', 'intermediate', 'final', null, 15, 'On a section flattened on TOP_A, which quantity sets the displayed span?', '["The deepest measured pick in the section, since that pick is the lowest thing on the panel.","The largest depth below the flattening top reached in any well.","The relief of the deepest surface across the wells.","The largest flattening shift in the section."]'::jsonb, 1, 'Flattening removes each well''s own TOP_A depth, so what remains is depth below the flattening top, and the largest of those distances is 150 m. Assuming the deepest measured pick wins is the classic error.'),
  ('wellcorrelation', 'intermediate', 'final', null, 16, 'Ekene-4 carries the deepest measured TOP_A, TOP_SAND and BASE_SAND in the section. Where does it draw on the flattened panel?', '["Shallowest of the four, with its deepest pick at 1535 m displayed, because it stopped 85 m below its own TOP_A.","Deepest of the four, with its deepest pick at 1615 m displayed.","Deepest of the four, since the largest shift moves it furthest down.","In the middle, because its shift of -80 cancels its depth."]'::jsonb, 0, 'Its deepest pick is BASE_SAND, and 1450 plus 85 gives 1535 m displayed. The deepest well in measured depth is the shallowest on the display, which is the counterexample worth remembering.'),
  ('wellcorrelation', 'intermediate', 'final', null, 17, 'Two picks in one well sit at measured depths a and b, and the well''s shift is s. What is the displayed interval?', '["b minus a, plus s, since the deeper pick has moved further than the shallower one.","b minus a, plus s.","b plus a, minus twice s.","b minus a, with the shift cancelled."]'::jsonb, 3, 'Both ends carry the same shift, so the displayed difference is b plus s minus a plus s, which is b minus a. Believing the deeper pick moves further is the misconception that makes a flattened section look untrustworthy.'),
  ('wellcorrelation', 'intermediate', 'final', null, 18, 'Is the 14 m growth range a property of the section or of the datum you chose?', '["Of the datum, since a different datum gives every well a different shift.","Of the datum, since the panel is redrawn each time.","Of the section.","Of both, because the intervals are read from the displayed column and that column moves."]'::jsonb, 2, 'Intervals survive flattening, so the growth range is the same whatever top and datum you flatten on. The displayed column moves and the differences within a well do not.'),
  ('wellcorrelation', 'intermediate', 'final', null, 19, 'Ekene-1 has TOP_SAND at a measured 1548 m and TOP_A at 1500 m. Where does TOP_SAND display on the 1450 m datum?', '["1598 m displayed, from 1548 plus the 50 m by which the well was moved.","48 m displayed.","1548 m displayed, since only TOP_A moves.","1498 m displayed."]'::jsonb, 3, 'The shift is 1450 minus 1500, which is -50, and 1548 plus -50 gives 1498 m displayed. Adding the magnitude of the shift is the sign error that always leaves the pick deeper than it started.'),
  ('wellcorrelation', 'intermediate', 'final', null, 20, 'Which of these is a structural quantity, defined on measured depths and untouched by flattening?', '["The 1503 m displayed depth of Ekene-2''s TOP_SAND on this datum.","The 14 m growth range.","The 150 m displayed span of the section.","The 35 m relief of TOP_A."]'::jsonb, 3, 'Relief is the measured spread of one surface across the wells that carry it, so no datum choice can alter it. The span and the displayed depth are properties of the picture, and growth is stratigraphic.'),
  ('wellcorrelation', 'intermediate', 'final', null, 21, 'Which question is answered by 14 m rather than by 49 m?', '["How much the thickness between TOP_A and TOP_SAND varies from well to well across the section.","How much TOP_SAND varies in depth across the section.","How deep the sand top sits below the datum.","How much relief TOP_SAND carries over four wells."]'::jsonb, 0, 'Two surfaces named means an interval, and variation in an interval is growth. One surface named means relief, which for TOP_SAND is 49 m measured.'),
  ('wellcorrelation', 'intermediate', 'final', null, 22, 'Which sentence is safe to put in a report?', '["TOP_SAND in Ekene-2 is at 1503 m, which is the value the flattened section panel gives for that pick in that well.","TOP_SAND in Ekene-2 is at 1503 m displayed.","TOP_SAND in Ekene-2 is at 1565 m measured and 1503 m displayed on the TOP_A datum at 1450 m.","TOP_SAND in Ekene-2 is between 1503 m and 1565 m."]'::jsonb, 2, 'A displayed depth means nothing without its datum and must never be written as a well depth. The trap is the sentence that offers a displayed number with no datum and no label.'),
  ('wellcorrelation', 'intermediate', 'final', null, 23, 'What are the four measured distances from each well''s own TOP_A down to its deepest pick?', '["140, 150, 133 and 85 m.","48, 53, 46 and 60 m, which are the A-to-SAND intervals of the four wells.","1640, 1662, 1628 and 1615 m.","50, 62, 45 and 80 m, which are the shifts."]'::jsonb, 0, 'Ekene-4''s deepest pick is BASE_SAND, giving 1615 minus 1530, which is 85 m, and the largest of the four is Ekene-2''s 150 m, which is the span. Substituting the shifts or the intervals is the common slip.'),
  ('wellcorrelation', 'intermediate', 'final', null, 24, 'Which list contains only quantities that flattening leaves unchanged?', '["Intervals within a well, structural relief, and the displayed depth of every pick below the datum.","Measured depths, displayed depths, and the displayed span.","Measured depths, intervals within a well, and structural relief.","Displayed depths and the growth range."]'::jsonb, 2, 'Flattening adds one shift per well at drawing time, so only displayed quantities move. The displayed span is computed from displayed depths and changes with the datum.'),
  ('wellcorrelation', 'intermediate', 'final', null, 25, 'Why is every flattening shift in this section negative?', '["Because the datum is deeper than every well''s TOP_A, so each column has to move down to reach it.","Because the 1450 m datum sits shallower than every well''s TOP_A, so each column has to move up the display to reach it.","Because the wells are ordered from shallow to deep across the panel.","Because a shift is always reported as a magnitude with a minus sign."]'::jsonb, 1, 'The shift is 1450 minus a TOP_A between 1495 and 1530, so all four are negative and every column moves up the display. If your deepest well moved down, the subtraction was reversed.'),
  ('wellcorrelation', 'intermediate', 'final', null, 26, 'One well shows an A-to-SAND interval far larger than the rest. What should you check first?', '["Whether that well''s shift was applied twice.","Whether TOP_SAND in that well was picked on the same sand as in the others, since a miscorrelation produces false growth.","Whether the datum depth was set too shallow.","Whether the displayed span has changed."]'::jsonb, 1, 'Growth is only as good as the picks behind it, since an interval assumes both surfaces are the same surfaces in every well. A large isolated interval is a reason to reopen the logs before writing about accommodation.'),
  ('wellcorrelation', 'intermediate', 'final', null, 27, 'Which depth belongs in a perforation memo for Ekene-4''s BASE_SAND?', '["Either of the two, since they describe the same surface in the same well.","1615 m measured.","1535 m displayed.","1535 m, taken from the flattened section panel."]'::jsonb, 1, 'Anything touching the physical well takes measured depth, and nothing in Ekene-4 is at 1535 m. Treating the two depths as interchangeable is what puts a display number into an operational document.'),
  ('wellcorrelation', 'intermediate', 'final', null, 28, 'Which subtraction produces a real interval?', '["Ekene-3''s BASE_SAND minus Ekene-3''s TOP_SAND.","Ekene-2''s displayed TOP_SAND minus Ekene-1''s measured TOP_A, once the shifts have been allowed for.","Ekene-4''s TOP_SAND minus Ekene-3''s TOP_A.","Ekene-2''s TOP_B minus its own flattening shift."]'::jsonb, 0, 'An interval is two picks in one wellbore, both on the same axis. Reaching across columns on a panel is easy with a cursor and gives a number with no thickness meaning.'),
  ('wellcorrelation', 'intermediate', 'final', null, 29, 'Flattening the Ekene section on TOP_A at a 1450 m datum, what is Ekene-3''s shift and why does it carry the sign it does?', '["45 m, since the well is the shallowest on the section and moves down to reach the datum.","-80 m, the largest shift on the section.","1495 m, the well''s own TOP_A pick.","-45 m, because Ekene-3 picks TOP_A at 1495 m and every TOP_A on this section is deeper than the 1450 m datum, so every well moves up the display and every shift is negative."]'::jsonb, 3, 'The shift is 1450 minus 1495. Reporting the magnitude without the sign is the classic error, because the sign is what records the direction the column moves.'),
  ('wellcorrelation', 'intermediate', 'final', null, 30, 'Ekene-1 picks TOP_SAND at 1548 m. What is its displayed depth on the section flattened on TOP_A at a 1450 m datum?', '["1598 m displayed, from 1548 plus a shift of 50 m, since the well moves down the display to bring its TOP_A onto a datum that sits above it.","1498 m displayed, from 1548 plus a shift of -50 m.","1450 m, because the flattening puts the displayed pick of every well onto the datum line.","1548 m."]'::jsonb, 1, 'Displayed equals the measured pick plus that well''s shift, and Ekene-1''s shift is 1450 minus 1500. Adding the magnitude instead of the signed shift is the classic error.'),
  ('wellcorrelation', 'intermediate', 'final', null, 31, 'Which well sets the minimum of the A-to-SAND growth range on the Ekene section, and at what interval?', '["Ekene-4 at 60 m, because a well that is missing a top constrains the thinnest part of the section and therefore has to supply the minimum of any range.","Ekene-1 at 48 m, the shallowest well on TOP_A.","Ekene-3 at 46 m, with Ekene-4 setting the maximum at 60 m and the range being 14 m.","Ekene-2 at 53 m."]'::jsonb, 2, 'The four intervals are 48, 53, 46 and 60 m, so the range is 60 minus 46. Assuming the well with the missing top must sit at an extreme for the wrong reason is the classic error, since Ekene-4 supplies the maximum rather than the minimum.'),
  ('wellcorrelation', 'intermediate', 'final', null, 32, 'You need the structural relief on TOP_A across the Ekene section. Which view do you read it in and what is the figure?', '["The measured view, and it is 35 m.","The flattened view at a 1450 m datum, where every TOP_A lands on the datum line, so the relief reads as zero and the surface is confirmed to be flat across the section.","Either view, because relief is a thickness and thicknesses do not depend on the frame.","The flattened view, where it reads 14 m."]'::jsonb, 0, 'Relief is a structural quantity and flattening on TOP_A removes exactly that relief by construction. Reading zero off the flattened panel is the classic error, and it is the correct reading of the wrong view.'),
  ('wellcorrelation', 'intermediate', 'final', null, 33, 'Ekene-1 picks TOP_B at 1640 m. Where does that pick draw on the section flattened on TOP_A at 1450 m, and what has to travel with the number?', '["At 1640 m, because TOP_B is not the flattening top and therefore does not move.","At 1690 m displayed, from 1640 plus 50 m.","It does not draw at all, because Ekene-4 lacks TOP_B.","At 1590 m displayed, from 1640 plus a shift of -50 m, and the word displayed has to travel with it, because the surface is still at 1640 m in the ground."]'::jsonb, 3, 'A well''s shift belongs to the well and applies to every top in it, TOP_B included. Quoting 1590 without the word displayed is the classic error, since a reader will take it for a depth in the ground.'),
  ('wellcorrelation', 'intermediate', 'final', null, 34, 'Ekene-3 picks TOP_B at 1628 m and takes a shift of -45 m. What is its displayed depth, and does it set the deep end of the displayed span?', '["1583 m displayed, and it does not set the deep end, which Ekene-2 supplies at 1600 m.","1583 m displayed, and it does set the deep end, because Ekene-3 is the shallowest well on TOP_A and therefore hangs lowest once every column has been pulled onto the datum.","1673 m displayed, from 1628 plus 45 m, and that value sets the deep end of the displayed span.","1628 m, unchanged."]'::jsonb, 0, 'Ekene-3''s TOP_B sits 133 m below its own TOP_A while Ekene-2''s sits 150 m below its own, so Ekene-2 draws deepest. Assuming the well with the largest shift or the shallowest datum pick supplies the deep end is the classic error.'),
  ('wellcorrelation', 'intermediate', 'final', null, 35, 'Suppose a fifth well joined the Ekene section carrying TOP_A, TOP_SAND and TOP_B but no BASE_SAND. What would the count of wells carrying all four tops become?', '["Four, because the new well carries TOP_B and therefore repairs the gap that Ekene-4 left in the section, bringing the number of complete columns up by one.","Three, because the new well fails the test exactly as Ekene-4 does, even though a different surface is the one missing.","Five, since five wells are now drawn on the section.","Four out of five."]'::jsonb, 1, 'The test is every one of the four surfaces rather than most of them, so a well missing any surface is excluded. Treating one well''s TOP_B as compensating for another well''s is the classic error.'),
  ('wellcorrelation', 'intermediate', 'final', null, 36, 'The Ekene tops table holds 15 picks in 16 slots and 3 of its 4 wells carry a complete column. Why does the capstone grade the second figure rather than the first?', '["Because the pick count changes when the section is flattened.","Because 15 is not an integer the grader is able to compare.","Because the well count is the harsher measure, since a section of many wells each missing one top would still score a very high pick count while having no complete column at all.","Because the two figures are always equal in practice."]'::jsonb, 2, 'The two measures move independently and the well count is the one that says how much complete data exists. Reading a high pick count as evidence of complete columns is the classic error.'),
  ('wellcorrelation', 'intermediate', 'final', null, 37, 'Which statement about the TOP_B correlation line can be made without naming the view it was read in?', '["That TOP_B sits at 1600 m in Ekene-2, because a displayed depth and a measured depth describe the same surface and are therefore interchangeable in a report.","That its deepest point on the section is 1662 m in Ekene-2 and its shallowest is 1628 m in Ekene-3.","That it is flat across the section.","That it reaches 3 of the 4 wells, because membership does not depend on the frame."]'::jsonb, 3, 'How many wells a line reaches is a property of the tops table, while every depth on it belongs to a view. Treating a displayed depth as interchangeable with a measured one is the classic error.'),
  ('wellcorrelation', 'intermediate', 'final', null, 38, 'You apply Ekene-4''s shift as 80 m instead of -80 m. By how much is every displayed depth in that well wrong?', '["By nothing, because the panel takes the magnitude of the shift and works out the direction from whether the datum sits above or below the well''s flattening pick.","By 160 m.","By 85 m, the well''s distance below its own TOP_A.","By 80 m, the size of the shift itself."]'::jsonb, 1, 'The pick moves 80 m the wrong way instead of 80 m the right way, so the error is twice the shift. Expecting the software to recover the direction is the classic error, since the sign is the only record of it.'),
  ('wellcorrelation', 'intermediate', 'final', null, 39, 'One surface other than the flattening top has been hand-edited in one well on a flattened section, and the well''s shift was left alone. Which quality control check catches it?', '["The check that computes an interval from the measured picks and again from the displayed ones and requires the two to agree.","The check that every well''s flattening top lands exactly on the datum, since a hand-edited pick anywhere in a well changes the shift that was computed for that whole well.","The check that the well count with all tops is stated.","The check that the displayed span is reported as a span."]'::jsonb, 0, 'Editing one end of an interval breaks the agreement between the measured and displayed versions of it. Expecting the datum check to catch it is the classic error, since that check only tests the flattening top.'),
  ('wellcorrelation', 'intermediate', 'final', null, 40, 'The Associate tier read the Ekene section and this tier flattens it. What does this tier add that the Associate tier could not produce?', '["The structural relief on each surface.","The picks themselves, made consistent across the project.","A measurement of how the section grows, since the Associate tier could say the TOP_A to TOP_SAND interval varies while this tier puts the figure of 14 m on that variation.","A prediction of Ekene-4''s missing TOP_B."]'::jsonb, 2, 'This tier turns a qualitative statement into a measured range of 14 m. Placing the prediction here is the classic error, since predicting the missing pick belongs to the tier above.'),
  ('wellcorrelation', 'intermediate', 'final', null, 41, 'You are writing up the flattened Ekene section. Which set of statements has to accompany the numbers?', '["The datum alone, because once a reader knows the datum sits at 1450 m they can convert any displayed depth back to a measured one by subtracting the datum from it.","The flattening top and the datum, the label measured or displayed on every depth, and the well count with all tops.","The four shifts and the growth range, since between them they let a reader rebuild every other figure on the section without any further labelling.","The tolerances used."]'::jsonb, 1, 'A reader needs the view, the frame of every depth and the denominator behind every statistic. Assuming the datum alone lets a depth be converted back is the classic error, since the conversion needs that well''s own shift.'),
  ('wellcorrelation', 'intermediate', 'final', null, 42, 'The growth range of 14 m and the TOP_B relief of 34 m are both quoted from the Ekene section. What is the difference a reader must be told?', '["There is no difference to report, because both figures are computed from the same tops table and the same four wells appear on the section that produced them.","The first is a displayed figure and the second is a measured one, so only the first needs its datum stated alongside it.","The first is expressed in metres while the second is expressed as a count.","The first rests on four wells and the second on three."]'::jsonb, 3, 'Every statistic inherits the wells that produced it, and TOP_B is a three-well surface here. Letting two figures with different denominators sit side by side unlabelled is the classic error.');
